using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class SandboxBoundaryCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-003";public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){var dir=RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance");string[] tokens=["api.ofac.gov","production-worldcheck","production-dowjones","prod-compliance-api-key"];var hits=Find(dir,tokens,ct);return Task.FromResult(new ReadinessCheck(Code,"Sandbox boundary",hits.Count==0?ReadinessStatus.Passed:ReadinessStatus.Failed,hits.Count==0?"No forbidden production provider endpoint detected":string.Join(", ",hits)));} private static List<string> Find(string dir,string[] tokens,CancellationToken ct){var hits=new List<string>();foreach(var file in RepositoryCheckUtilities.EnumerateTextFiles(dir)){ct.ThrowIfCancellationRequested();var content=File.ReadAllText(file);foreach(var token in tokens)if(content.Contains(token,StringComparison.OrdinalIgnoreCase))hits.Add($"{Path.GetFileName(file)}:{token}");}return hits;} }